    "ralentit les ennemis autour de l'impact, empoisonne l'ennemi et l'ennemi perd le nord et recule": "rallenta i nemici intorno all'impatto, avvelena il nemico e il nemico perde la bussola e indietreggia",
    "rebondit sur 3 ennemis": "rimbalza su 3 nemici",
    "rebondit sur 3 ennemis et recharge ton bouclier plus vite": "rimbalza su 3 nemici e ricarica più in fretta il tuo scudo",
    "rebondit sur un autre ennemi et te soigne à chaque coup": "rimbalza su un altro nemico e ti cura a ogni colpo",
