    "rebondit sur un autre ennemi, repousse l'ennemi et te soigne à chaque coup": "rimbalza su un altro nemico, respinge il nemico e ti cura a ogni colpo",
    "recharge ton bouclier plus vite et repousse les ennemis autour": "ricarica più in fretta il tuo scudo e respinge i nemici intorno",
    "recharge ton bouclier plus vite, repousse les ennemis autour et ralentit les ennemis autour de l'impact": "ricarica più in fretta il tuo scudo, respinge i nemici intorno e rallenta i nemici intorno all'impatto",
    "repousse les ennemis autour et achève les ennemis presque morts": "respinge i nemici intorno e finisce i nemici quasi morti",
    "repousse les ennemis autour et fait brûler tous les ennemis autour": "respinge i nemici intorno e fa bruciare tutti i nemici intorno",
    "repousse les ennemis autour et l'ennemi subit +{weakenBonus}% de dégâts pendant {weakenDuration} s": "respinge i nemici intorno e il nemico subisce +{weakenBonus}% di danni per {weakenDuration} s",
    "repousse les ennemis autour, achève les ennemis presque morts et recharge ton bouclier plus vite": "respinge i nemici intorno, finisce i nemici quasi morti e ricarica più in fretta il tuo scudo",
    "repousse les ennemis autour, fait saigner l'ennemi (les saignements s'additionnent) et l'ennemi subit +{weakenBonus}% de dégâts pendant {weakenDuration} s": "respinge i nemici intorno, fa sanguinare il nemico (i sanguinamenti si sommano) e il nemico subisce +{weakenBonus}% di danni per {weakenDuration} s",
    "se divise en 3 projectiles vers d'autres ennemis et la balle revient vers sa planète en touchant tout sur son passage": "si divide in 3 proiettili verso altri nemici e il proiettile torna al suo pianeta colpendo tutto ciò che incontra",
    "se divise en 3 projectiles vers d'autres ennemis et te soigne à chaque coup": "si divide in 3 proiettili verso altri nemici e ti cura a ogni colpo",
    "te soigne à chaque coup et ralentit les ennemis autour de l'impact": "ti cura a ogni colpo e rallenta i nemici intorno all'impatto",
    "te soigne à chaque coup et se divise en 3 projectiles vers d'autres ennemis": "ti cura a ogni colpo e si divide in 3 proiettili verso altri nemici",
    "te soigne à chaque coup, charme l'ennemi : il fait demi-tour et blesse ses alliés et enracine les ennemis autour": "ti cura a ogni colpo, incanta il nemico: torna indietro e ferisce i suoi alleati e imprigiona nelle radici i nemici intorno",
    "te soigne à chaque coup, charme l'ennemi : il fait demi-tour et blesse ses alliés et rebondit sur un autre ennemi": "ti cura a ogni colpo, incanta il nemico: torna indietro e ferisce i suoi alleati e rimbalza su un altro nemico",
    "te soigne à chaque coup, charme l'ennemi : il fait demi-tour et blesse ses alliés et recharge ton bouclier plus vite": "ti cura a ogni colpo, incanta il nemico: torna indietro e ferisce i suoi alleati e ricarica più in fretta il tuo scudo",
    "te soigne à chaque coup, charme l'ennemi : il fait demi-tour et blesse ses alliés et éclate en 2 projectiles vers d'autres ennemis": "ti cura a ogni colpo, incanta il nemico: torna indietro e ferisce i suoi alleati ed esplode in 2 proiettili verso altri nemici",
    "te soigne à chaque coup, enracine les ennemis autour et ralentit les ennemis autour de l'impact": "ti cura a ogni colpo, imprigiona nelle radici i nemici intorno e rallenta i nemici intorno all'impatto",
    "te soigne à chaque coup, enracine les ennemis autour et recharge ton bouclier plus vite": "ti cura a ogni colpo, imprigiona nelle radici i nemici intorno e ricarica più in fretta il tuo scudo",
    "te soigne à chaque coup, enracine les ennemis autour et éclate en 2 projectiles vers d'autres ennemis": "ti cura a ogni colpo, imprigiona nelle radici i nemici intorno ed esplode in 2 proiettili verso altri nemici",
    "te soigne à chaque coup, fait brûler tous les ennemis autour et charme l'ennemi : il fait demi-tour et blesse ses alliés": "ti cura a ogni colpo, fa bruciare tutti i nemici intorno e incanta il nemico: torna indietro e ferisce i suoi alleati",
    "te soigne à chaque coup, ralentit les ennemis autour de l'impact et charme l'ennemi : il fait demi-tour et blesse ses alliés": "ti cura a ogni colpo, rallenta i nemici intorno all'impatto e incanta il nemico: torna indietro e ferisce i suoi alleati",
    "te soigne à chaque coup, ralentit les ennemis autour de l'impact et enracine les ennemis autour": "ti cura a ogni colpo, rallenta i nemici intorno all'impatto e imprigiona nelle radici i nemici intorno",
