    "+500 nectar": "+500 nettare",
    "Aucune autre quête possible pour l'instant": "Nessun'altra missione disponibile per ora",
    "Pub fermée trop tôt : la quête ne change pas": "Pubblicità chiusa troppo presto: la missione non cambia",
    "✅ Quête du jour terminée : {quest}": "✅ Missione del giorno completata: {quest}",
    "🎁 +{gold} or, +{xp} XP, +{nectar} nectar": "🎁 +{gold} oro, +{xp} XP, +{nectar} nettare",
    "Pas assez de nectar ({price} 🍯)": "Nettare insufficiente ({price} 🍯)",
    "✨ {name} rejoint ta collection !": "✨ {name} entra nella tua collezione!",
    "Ennemis pressés : +{percent} % de vitesse": "Nemici frettolosi: +{percent}% di velocità",
    "Ennemis coriaces : +{percent} % de vie": "Nemici coriacei: +{percent}% di vita",
    "Nuée : les ennemis arrivent {percent} % plus souvent": "Sciame: i nemici arrivano il {percent}% più spesso",
    "Monstres en avance : les super ennemis arrivent {times} fois plus tôt": "Mostri in anticipo: i super nemici arrivano {times} volte prima",
    "Pas de régénération : ta vie ne remonte pas avec le temps": "Nessuna rigenerazione: la tua vita non risale col tempo",
    "Canon de verre : vie max ×{health}, dégâts ×{damage}": "Cannone di vetro: vita max ×{health}, danni ×{damage}",
    "Seules les planètes tirent : toi, tu ne tires pas": "Sparano solo i pianeti: tu no",
    "🥉 tenir jusqu'à {time} · 🥈 voir {boss} arriver · 🥇 le vaincre": "🥉 resisti fino a {time} · 🥈 vedi arrivare {boss} · 🥇 sconfiggilo",
    "Objectif : survivre le plus longtemps possible": "Obiettivo: sopravvivi il più a lungo possibile",
    "Objectif : tuer le plus d'ennemis possible": "Obiettivo: uccidi più nemici possibile",
    "Objectif : vaincre {boss}": "Obiettivo: sconfiggi {boss}",
    "Départ : ta progression (tes dieux, tes compétences, ton shop), sans or ni XP en poche.": "Partenza: i tuoi progressi (dèi, abilità, shop), senza oro né XP in tasca.",
    "Départ : {gods} imposés, arbres vides. Répartis ton XP dans leurs compétences et dépense {gold} or au shop.": "Partenza: {gods} imposti, alberi vuoti. Distribuisci la tua XP nelle loro abilità e spendi {gold} oro nello shop.",
    "Départ : {gods} imposés, avec des voies déjà prises. Pas d'XP en plus : place bien les planètes pour les combos et dépense {gold} or au shop.": "Partenza: {gods} imposti, con vie già scelte. Niente XP in più: posiziona bene i pianeti per le combo e spendi {gold} oro nello shop.",
    "Lancer le défi du jour ? Ta partie en cours s'arrête (l'or et l'XP gagnés sont gardés).": "Avviare la sfida del giorno? La partita in corso si ferma (oro e XP guadagnati restano).",
    "{medal} Médaille gagnée !": "{medal} Medaglia ottenuta!",
    "Prépare-toi avant de lancer : touche ✦ Skills pour les compétences, et la languette du Shop en bas.": "Preparati prima di partire: tocca ✦ Skills per le abilità e la linguetta dello Shop in basso.",
    "Prépare-toi avant de lancer : ✦ Skills (S) pour les compétences, et la languette du Shop en bas (B).": "Preparati prima di partire: ✦ Skills (S) per le abilità e la linguetta dello Shop in basso (B).",
    "Étape {step} / 3": "Tappa {step} / 3",
    "Meilleur essai du jour : {best} {medal} · essais : {attempts}": "Miglior tentativo di oggi: {best} {medal} · tentativi: {attempts}",
    "+{nectar} nectar 🍯": "+{nectar} nettare 🍯",
    "🔁 Réessayer le défi (R)": "🔁 Riprova la sfida (R)",
    "3 nouvelles quêtes chaque jour à minuit. Elles avancent pendant tes parties normales (le temps sauté ne compte pas).": "3 nuove missioni ogni giorno a mezzanotte. Avanzano durante le tue partite normali (il tempo saltato non conta).",
    "+{gold} or · +{xp} XP · +{nectar} 🍯": "+{gold} oro · +{xp} XP · +{nectar} 🍯",
    "✔ Récupérée": "✔ Riscattata",
    "Récupérer": "Riscatta",
    "🔄 Changer": "🔄 Cambia",
    "🔄 Changer (pub)": "🔄 Cambia (pubblicità)",
    "Une fois par jour : remplace cette quête par une autre de la même difficulté": "Una volta al giorno: sostituisci questa missione con un'altra della stessa difficoltà",
    "Coffre du jour": "Forziere del giorno",
    "Les 3 quêtes récupérées : +{gold} or · +{xp} XP · +{nectar} 🍯": "Le 3 missioni riscattate: +{gold} oro · +{xp} XP · +{nectar} 🍯",
    "🔥 Série : {days} jour(s) · +{percent} % de nectar dans le coffre (rater un jour divise la série par 2)": "🔥 Serie: {days} giorno/i · +{percent}% di nettare nel forziere (saltare un giorno dimezza la serie)",
    "Ouvrir": "Apri",
    "💰 Doubler": "💰 Raddoppia",
    "💰 Doubler (pub)": "💰 Raddoppia (pubblicità)",
    "Une partie à part, la même pour tout le monde aujourd'hui : un départ, des règles et un objectif tirés au sort. Ta vraie partie n'est pas touchée : seules les médailles rapportent du nectar.": "Una partita a parte, uguale per tutti oggi: partenza, regole e obiettivo estratti a sorte. La tua vera partita non cambia: solo le medaglie danno nettare.",
    "Nectar des médailles (la meilleure du jour) : {list} 🍯": "Nettare delle medaglie (la migliore del giorno): {list} 🍯",
    "Ton meilleur essai : {best} {medal} · essais : {attempts}": "Il tuo miglior tentativo: {best} {medal} · tentativi: {attempts}",
    "▶ Jouer le défi du jour": "▶ Gioca la sfida del giorno",
    "Débloqué dès ton 1er dieu en orbite.": "Sbloccata con il tuo primo dio in orbita.",
    "Tous les paliers !": "Tutti i livelli!",
    "Le nectar se gagne avec les quêtes, le défi du jour et les succès. La collection ne change que l'apparence : jamais les règles du jeu.": "Il nettare si guadagna con missioni, sfida del giorno e obiettivi. La collezione cambia solo l'aspetto: mai le regole del gioco.",
    "✔ Porté": "✔ Indossato",
    "Porter": "Indossa",
    "Quitter le défi et revenir à ta partie ? Cet essai ne compte pas.": "Abbandonare la sfida e tornare alla tua partita? Questo tentativo non conta.",
    "Tue {n} ennemis": "Uccidi {n} nemici",
    "Joue {n} parties": "Gioca {n} partite",
    "Achète {n} améliorations dans le shop": "Compra {n} potenziamenti nello shop",
    "Prends {n} compétences": "Prendi {n} abilità",
    "Joue {time} au total": "Gioca {time} in totale",
    "Fais {n} coups critiques": "Fai {n} colpi critici",
    "Tue {n} ennemis avec la planète de {god}": "Uccidi {n} nemici con il pianeta di {god}",
    "Survis {time} en une partie": "Sopravvivi {time} in una partita",
